% Decision variables: each digit from 1 to 9 (no leading zeros for two‐digit numbers)
var 1..9: a;
var 1..9: b;
var 1..9: c;
var 1..9: d;

% All digits are distinct
constraint all_different([a,b,c,d]);

% Define two‐digit numbers
% ab = 10*a + b
% bc = 10*b + c
% cd = 10*c + d
% da = 10*d + a

% cd is 3 times ab
constraint (c * 10 + d) = 3 * (a * 10 + b);

% da is 2 times bc
constraint (d * 10 + a) = 2 * (b * 10 + c);

solve satisfy;

% Output as JSON
output [
  "{",
    "\"a\": ", show(a), ",",
    "\"b\": ", show(b), ",",
    "\"c\": ", show(c), ",",
    "\"d\": ", show(d),
  "}"
];
```

