include "globals.mzn";

% Number of moves (fixed to 20) and total steps to climb
int: num_moves = 20;
int: total_steps = 20;

% Allowed step sizes: 3, 4, 5 or 0 (for unused moves after reaching the top)
array[1..num_moves] of var {0,3,4,5}: steps;

% 1) Sum of all moves must exactly equal the staircase height
constraint
  sum(i in 1..num_moves)(steps[i]) = total_steps;

% 2) Once a zero move occurs, all subsequent moves must also be zero
constraint
  forall(i in 1..num_moves-1)(
    steps[i] = 0 -> steps[i+1] = 0
  );

solve satisfy;

output [
  "{",
  "\"steps\": ", show(steps),
  "}"
];
```

