include "globals.mzn";

% Number of countries
int: num_countries = 6;

% Adjacency pairs (i,j) meaning country i is adjacent to country j
array[1..9, 1..2] of int: graph = 
  array2d(1..9, 1..2, [
    3,1,
    3,6,
    3,4,
    6,4,
    6,1,
    1,5,
    1,4,
    4,5,
    4,2
  ]);

% Decision variables: colour assigned to each country (1=Belgium,2=Denmark,3=France,4=Germany,5=Netherlands,6=Luxembourg)
array[1..num_countries] of var 1..num_countries: colors;

% Number of colours used: the maximum colour index actually assigned
var 1..num_countries: num_colors;

% Ensure neighbouring countries have different colours
constraint
  forall(e in 1..9) (
    let {
      int: i = graph[e,1],
      int: j = graph[e,2]
    } in
      colors[i] != colors[j]
  );

% Define the number of colours as the maximum value in the colours array
constraint num_colors = max(colors);

% Minimize the number of colours used
solve minimize num_colors;

% Output the solution in JSON format
output [
  "{",
    "\"" ++ "colors" ++ "\": " ++ show(colors),
  "}"
];
```

