% We have 5 matchings (slots) that bind a child, age, country, and story.
% Codes:
%  children: 1=Bernice,2=Carl,3=Debby,4=Sammy,5=Ted
%  ages    : actual values {3,5,7,8,10}
%  countries: 1=Ethiopia,2=Kazakhstan,3=Lithuania,4=Morocco,5=Yemen
%  stories : 1=burning bush,2=captivity,3=Moses’s youth,4=Passover,5=Ten Commandments

% Decision variables:
array[1..5] of var {3,5,7,8,10}: ages;        % actual ages
array[1..5] of var 1..5: children;            % child code
array[1..5] of var 1..5: countries;           % country code
array[1..5] of var 1..5: stories;             % story code

% All assignments must be permutations:
constraint all_different(children);
constraint all_different(countries);
constraint all_different(stories);
constraint all_different(ages);

% Helper: find slot index for a given child, country, or story
function var int: idx_child(int: c) = 
    let { var int: i } in (i where children[i] = c);
function var int: idx_country(int: c) = 
    let { var int: i } in (i where countries[i] = c);
function var int: idx_story(int: s) = 
    let { var int: i } in (i where stories[i] = s);

% 1. Debby’s family is from Lithuania.
constraint countries[idx_child(3)] = 3;

% 2. The child who told Passover (4) is two years older than Bernice (child 1).
constraint ages[idx_story(4)] = ages[idx_child(1)] + 2;

% 3. The child from Yemen (5) is younger than the child from Ethiopia (1).
constraint ages[idx_country(5)] < ages[idx_country(1)];

% 4. The child from Morocco (4) is three years older than Ted (child 5).
constraint ages[idx_country(4)] = ages[idx_child(5)] + 3;

% 5. Sammy (child 4) is three years older than the child who told Moses’s youth (3).
constraint ages[idx_child(4)] = ages[idx_story(3)] + 3;

solve satisfy;

output [
  "{",
    join(",", [
      "\"ages\": " ++ show(ages),
      "\"children\": " ++ show(children),
      "\"countries\": " ++ show(countries),
      "\"stories\": " ++ show(stories)
    ]),
  "}"
];
```

