include "globals.mzn";

% There are 25 cows producing milk equal to their index (1..25).
% We have 5 sons (indexed 0..4) who should each get a fixed number of cows:
% 7, 6, 5, 4, 3 respectively, and each son's cows must sum to 65 kg of milk.

% Decision variable: for each cow i (1..25), assign to son 0..4
array[1..25] of var 0..4: cow_assignments;

% Auxiliary: total milk sum for each son s in 0..4
array[0..4] of var 0..325: sumS;

% Enforce each son gets the required number of cows
constraint
  global_cardinality(cow_assignments,
                     [0,1,2,3,4],
                     [7,6,5,4,3]);

% Compute sum of milk for each son and require it equals 65
constraint
  forall(s in 0..4) (
    sumS[s] = sum(i in 1..25)( i * bool2int(cow_assignments[i] == s) )
  ) /\
  forall(s in 0..4) (
    sumS[s] = 65
  );

solve satisfy;

output [
  "{",
    "\"cow_assignments\": ", show(cow_assignments),
  "}"
];
```

