include "globals.mzn";

% We want four item prices in cents that sum to 711 and whose product is 711000000.
% Define decision variables: prices[1..4] each between 1 and 711 cents.
array[1..4] of var 1..711: prices;

% Constraint: sum of prices is 711 cents ($7.11)
constraint sum(i in 1..4)(prices[i]) = 711;

% Constraint: product of prices equals 711000000 (because 
% (p1/100)*(p2/100)*(p3/100)*(p4/100) = 7.11
% => p1*p2*p3*p4 = 7.11 * 100^4 = 7.11 * 100000000 = 711000000)
constraint prices[1] * prices[2] * prices[3] * prices[4] = 711000000;

% Symmetry breaking: enforce non-decreasing order
constraint forall(i in 1..3)(prices[i] <= prices[i+1]);

solve satisfy;

% Output the prices array in JSON format under the key "prices"
output [
    "{",
    "\"prices\": ", show(prices),
    "}"
];
```

