% Decision variables: apples before each gate (1..5) and after last gate (6)
array[1..6] of var int: apples;

% The boy ends with 1 apple before giving to the girl
constraint apples[6] = 1;

% For each gate i:
%  - apples[i] must be even (so half is integer)
%  - after giving half plus one, the remainder is apples[i+1]
constraint
  forall(i in 1..5) (
    apples[i] mod 2 = 0 /\
    apples[i+1] = apples[i] div 2 - 1
  );

solve satisfy;

output [
  "{",
    "\"apples\": ", show(apples),
  "}"
];
```

