```minizinc
include "globals.mzn";

% Input data
int: num_people = 8;
set of int: PEOPLE = 1..num_people;
array[PEOPLE] of set of PEOPLE: compatible = [
    {2, 3},
    {1, 6},
    {1, 4, 7},
    {2},
    {2},
    {5},
    {8},
    {3}
];

% Decision variables: transplants[i,j] = 1 if i gives to j
array[PEOPLE, PEOPLE] of var 0..1: transplants;

% Constraints

% Only allow donations where compatible
constraint
  forall(i, j in PEOPLE where not (j in compatible[i])) (
    transplants[i,j] = 0
  );

% At most one kidney donated per person
constraint
  forall(i in PEOPLE) (
    sum(j in PEOPLE)(transplants[i,j]) <= 1
  );

% At most one kidney received per person
constraint
  forall(j in PEOPLE) (
    sum(i in PEOPLE)(transplants[i,j]) <= 1
  );

% Anyone who gives must receive one (and to form disjoint cycles)
constraint
  forall(i in PEOPLE) (
    sum(j in PEOPLE)(transplants[i,j])
    =
    sum(k in PEOPLE)(transplants[k,i])
  );

% Maximize number of transplants
solve maximize sum(i, j in PEOPLE)(transplants[i,j]);

% Output in JSON format
output [
  "{",
    "\"transplants\": ", show(transplants),
  "}"
];
```

