```minizinc
include "globals.mzn";

% Dimension of the magic square
int: n = 4;
int: n2 = n * n;

% The magic sum for each row, column, and diagonal
var int: s = n * (n2 + 1) div 2;

% Decision variables: an n×n grid of distinct values from 1..n^2
array[1..n, 1..n] of var 1..n2: x;

% All cells must be pairwise different
constraint all_different([ x[i,j] | i,j in 1..n ]);

% Row sums
constraint forall(i in 1..n)(
    sum([ x[i,j] | j in 1..n ]) == s
);

% Column sums
constraint forall(j in 1..n)(
    sum([ x[i,j] | i in 1..n ]) == s
);

% Main diagonal sum
constraint sum([ x[i,i] | i in 1..n ]) == s;

% Secondary diagonal sum
constraint sum([ x[i,n+1-i] | i in 1..n ]) == s;

solve satisfy;

% Output the magic square as a JSON list of lists under the key "square"
output [
    "{",
      "\"square\": [",
        join(
          ",",
          [ "[" ++ join(",", [ show(x[i,j]) | j in 1..n ]) ++ "]"
            | i in 1..n
          ]
        ),
      "]",
    "}"
];
```

