```minizinc
include "globals.mzn";

% Input data
int: n = 8;
array[1..n] of set of int: adjacency_list = [
    {2, 3, 7},
    {1, 4, 8},
    {1, 4, 5},
    {2, 3, 6},
    {3, 6, 7},
    {4, 5, 8},
    {1, 5, 8},
    {2, 6, 7}
];

% Decision variables: whether each node is in the independent set
array[1..n] of var bool: nodes;

% Constraint 1: independence -- no two adjacent nodes both selected
constraint
  forall(i in 1..n, j in adjacency_list[i]) (
    not(nodes[i] /\ nodes[j])
  );

% Constraint 2: maximality -- any node not in the set has at least one neighbor in it
constraint
  forall(i in 1..n) (
    bool2int(nodes[i]) +
    sum([ bool2int(nodes[j]) | j in adjacency_list[i] ]) 
    >= 1
  );

solve satisfy;

% Output the selection as a JSON array of 0/1 indicators
output [
  "{",
  "\"nodes\": [" ++ join(",", [ show(bool2int(nodes[i])) | i in 1..n ]) ++ "]",
  "}"
];
```

