% Number of people
int: n = 13;
int: total_females = 9;
int: total_males = n - total_females;

% Decision variable: 1 = female, 0 = male
array[1..n] of var 0..1: sequence;

% Ensure exactly 9 females and 4 males
constraint sum(sequence) == total_females;

% First person must be male to avoid division by zero issues
constraint sequence[1] == 0;

% At every prefix, number of females to males <= 7/3
% Let f = #females in prefix, m = #males in prefix = i - f
% Enforce 3*f <= 7*m for all prefixes i
constraint
  forall(i in 1..n) (
    let {
      var int: f = sum(j in 1..i)(sequence[j]),
      var int: m = i - f
    } in
      3 * f <= 7 * m
  );

solve satisfy;

output [
  "{",
    "\"sequence\": ", show(sequence),
  "}"
];
```

