% Number of 4‐hour time slots
int: num_slots = 6;

% Demand for buses in each time slot
array[1..num_slots] of int: demands = [4, 8, 10, 7, 12, 4];

% Since each bus can work at most two consecutive slots,
% we define the number of buses starting their 8‐hour shift at slot i
int: num_starts = num_slots - 1;
array[1..num_starts] of var 0..max(demands): s;

% x[j] is the number of buses available in slot j
array[1..num_slots] of var 0..2*max(demands): x;

% Link the start variables to availability in each slot:
% - In slot 1, only buses that start at 1 are available
constraint x[1] = s[1];
% - In the last slot, only buses that started at the previous slot are still working
constraint x[num_slots] = s[num_starts];
% - In intermediate slots, sum of those who started in the current or previous slot
constraint forall(j in 2..num_slots-1)(
    x[j] = s[j-1] + s[j]
);

% Ensure demand is met in every slot
constraint forall(j in 1..num_slots)(
    x[j] >= demands[j]
);

% Minimize the total number of buses (each bus counted once at its start)
var int: total_buses = sum(i in 1..num_starts)(s[i]);
solve minimize total_buses;

% Output the schedule as JSON with key "x"
output [
    "{",
    "\"x\": ", show(x),
    "}"
];
```

