% Data
int: num_jobs = 3;
int: max_tasks = 3;  % maximum number of tasks in any job
int: num_machines = 3;

% Number of tasks per job
array[1..num_jobs] of int: num_tasks = [3, 3, 2];

% Machine assignment for each job-task (0-based machines)
array[1..num_jobs, 1..max_tasks] of int: machine = array2d(
    1..num_jobs, 1..max_tasks,
    [ 0, 1, 2,
      0, 2, 1,
      1, 2, 0  % dummy machine for job 3 task 3
    ]
);

% Duration of each job-task (0 for non-existing tasks)
array[1..num_jobs, 1..max_tasks] of int: duration = array2d(
    1..num_jobs, 1..max_tasks,
    [ 3, 2, 2,
      2, 1, 4,
      4, 3, 0
    ]
);

% Upper bound on schedule length
int: horizon = sum([ duration[j,t] | j in 1..num_jobs, t in 1..max_tasks ]);

% Decision variables: start times
array[1..num_jobs, 1..max_tasks] of var 0..horizon: s;

% Makespan to minimize
var 0..horizon: makespan;

% 1) Precedence: each task starts after its predecessor finishes
constraint
  forall(j in 1..num_jobs, t in 2..num_tasks[j]) (
    s[j,t] >= s[j,t-1] + duration[j,t-1]
  );

% 2) No overlap on the same machine (disjunctive constraints)
constraint
  forall(j1 in 1..num_jobs, t1 in 1..max_tasks,
         j2 in 1..num_jobs, t2 in 1..max_tasks
         where 
           % both tasks exist
           t1 <= num_tasks[j1] /\ t2 <= num_tasks[j2] /\
           % assigned to same machine
           machine[j1,t1] = machine[j2,t2] /\
           % enforce each pair only once
           ( j1 < j2 \/ (j1 = j2 /\ t1 < t2) )
  ) (
    (s[j1,t1] + duration[j1,t1] <= s[j2,t2])
    \/
    (s[j2,t2] + duration[j2,t2] <= s[j1,t1])
  );

% 3) Define makespan as the maximum completion time
constraint
  forall(j in 1..num_jobs, t in 1..num_tasks[j]) (
    makespan >= s[j,t] + duration[j,t]
  );

% Objective: minimize the makespan
solve minimize makespan;

% Output result as JSON
output [
  "{\"makespan\": ", show(makespan), "}"
];
