    | 0, 1, X, 4, X, X, X, 3
    | 0, 1, 2, X, 2, 3, X, 2
];

int: rows = 8;
int: cols = 8;

% Decision variables: 1 if there is a mine, 0 otherwise
array[1..rows, 1..cols] of var 0..1: mines;

