constraint
  forall(r in 1..rows, c in 1..cols where game_data[r,c] != X) (
    sum([
      mines[r+dr, c+dc]
      | dr in -1..1, dc in -1..1
      where not (dr = 0 /\ dc = 0)
        /\ r+dr in 1..rows
        /\ c+dc in 1..cols
    ]) = game_data[r,c]
  );

solve satisfy;

output [
  "{",
     "\"mines\": ", show(mines),
  "}"
];
