% Number of items
int: n = 4;

% Input data: widths and heights of each item
array[1..n] of int: widths = [3, 4, 2, 1];
array[1..n] of int: heights = [2, 3, 1, 4];

% Compute bounds for the container dimensions
int: sum_widths  = sum(widths);
int: sum_heights = sum(heights);
int: max_width   = max(widths);
int: max_height  = max(heights);

% Decision variables: container size
var max_width..sum_widths:  total_x;
var max_height..sum_heights: total_y;

% Decision variables: positions of items
array[1..n] of var 0..sum_widths:  pos_x;
array[1..n] of var 0..sum_heights: pos_y;

% Ensure each item lies within the container boundaries
constraint
  forall(i in 1..n) (
    pos_x[i] + widths[i]  <= total_x /\
    pos_y[i] + heights[i] <= total_y
  );

% Non-overlap constraint using the global diffn constraint
constraint
  diffn(pos_x, pos_y, widths, heights);

% Objective: minimize the area of the container
solve minimize total_x * total_y;

% Output the positions and container dimensions in JSON format
output [
  "{",
    join(",", [
      "\"pos_x\": " ++ show(pos_x),
      "\"pos_y\": " ++ show(pos_y),
      "\"total_x\": " ++ show(total_x),
      "\"total_y\": " ++ show(total_y)
    ]),
  "}"
];
