% Define job and resource sets
set of int: JOBS = 0..11;
int: n_res = 2;
set of int: RES = 1..n_res;

% Input data
array[JOBS] of int: durations_data = [0, 3, 2, 5, 4, 2, 3, 4, 2, 4, 6, 0];
array[JOBS, RES] of int: resource_needs_data = array2d(
  JOBS, RES,
  [ 0,0,  5,1,  0,4,  1,4,  1,3,  3,2,
    3,1,  2,4,  4,0,  5,2,  2,5,  0,0 ]
);
array[RES] of int: resource_capacities_data = [6, 8];

% Precedence relations: (pred, succ)
int: num_succ = 18;
array[1..num_succ, 1..2] of int: successors_link_data = array2d(
  1..num_succ, 1..2,
  [  0, 1,  0, 2,  0, 3,  1, 4,  1, 5,  2, 9,  2,10,  3, 8,
     4, 6,  4, 7,  5, 9,  5,10,  6, 8,  6, 9,  7, 8,  8,11,
     9,11, 10,11 ]
);

% Compute an upper bound on the project horizon
int: horizon = sum(j in JOBS)(durations_data[j]);

% Decision variables
array[JOBS] of var 0..horizon: start_time;
array[JOBS] of var 0..horizon: d;    % duration as var to use in cumulative
array[JOBS, RES] of var 0..max(resource_capacities_data): r; % resource needs as var
var 0..horizon: makespan;

% Fix durations and resource needs to input data
constraint forall(j in JOBS) (
  d[j] = durations_data[j]
);
constraint forall(j in JOBS, res in RES) (
  r[j,res] = resource_needs_data[j,res]
);

% Precedence constraints
constraint
  forall(k in 1..num_succ) (
    let {
      int: pred = successors_link_data[k,1],
      int: succ = successors_link_data[k,2]
    } in
      start_time[succ] >= start_time[pred] + d[pred]
  );

% Define makespan as the maximum completion time
constraint
  maximum(makespan, [ start_time[j] + d[j] | j in JOBS ]);

% Resource capacity constraints for each resource via cumulative
constraint
  forall(res in RES) (
    cumulative(
      start_time,
      d,
      [ r[j,res] | j in JOBS ],
      resource_capacities_data[res]
    )
  );

% Objective: minimize the makespan
solve minimize makespan;

% Output start times in JSON format
output [
  "{",
    "\"start_time\": ", show(start_time),
  "}"
];
