include "globals.mzn";

% Input data
int: max_rooms = 5;                % Maximum number of rooms available
int: num_requests = 4;             % Number of requests

% Map dates to integer days: "2024-05-01" -> 1, ..., "2024-05-08" -> 8
array[1..num_requests] of int: start_dates = [1, 2, 3, 4];
array[1..num_requests] of int: end_dates   = [5, 6, 7, 8];

% Pre-assigned rooms: -1 means no pre-assignment
array[1..num_requests] of int: preassigned = [3, -1, -1, -1];

% Decision variables: room assigned to each request
array[1..num_requests] of var 1..max_rooms: room_assignments;

% Respect pre-assignments
constraint
  forall(i in 1..num_requests) (
    if preassigned[i] != -1 then
      room_assignments[i] = preassigned[i]
    else
      true
    endif
  );

% No overlapping requests in the same room
% Using inclusive dates: two requests i and j overlap if not (end_i < start_j or end_j < start_i)
constraint
  forall(i, j in 1..num_requests where i < j) (
    room_assignments[i] != room_assignments[j]
    \/ end_dates[i] < start_dates[j]
    \/ end_dates[j] < start_dates[i]
  );

solve satisfy;

% Output the assignments in JSON format
output [
  "{",
    "\"room_assignments\": ", show(room_assignments),
  "}"
];
```

