include "globals.mzn";

% Number of persons
int: N = 3;
% Names for reference (not used in constraints)
array[1..N] of string: names = ["Agatha herself", "the butler", "Charles"];

% hates[i,j] = true if person i hates person j
array[1..N, 1..N] of var bool: hates;

% wealth[i] is the wealth level of person i (1 = poorest, 3 = richest)
array[1..N] of var 1..3: wealth;

% killer is the index of the murderer
var 1..N: killer;

% 1) Agatha hates everybody except the butler
constraint
  forall(j in 1..N) (
    if j = 2 then
      hates[1, j] = false
    else
      hates[1, j] = true
    endif
  );

% 2) Butler hates everyone not richer than Agatha OR everyone whom Agatha hates
constraint
  forall(j in 1..N) (
    (wealth[j] <= wealth[1] \/ hates[1, j]) -> hates[2, j]
  );

% 3) Charles hates no one that Agatha hates
constraint
  forall(j in 1..N) (
    hates[1, j] -> not hates[3, j]
  );

% 4) No one hates everyone
constraint
  forall(i in 1..N) (
    exists(j in 1..N) (not hates[i, j])
  );

% 5) The killer always hates the victim (Agatha, index 1)
%    and is no richer than the victim
constraint
  hates[killer, 1];
constraint
  wealth[killer] <= wealth[1];

solve satisfy;

output [
  "{",
  "\"killer\": ", show(killer),
  "}"
];
```

