include "globals.mzn";

% Number of stages (including initial and final)
int: stage = 8;
set of int: STAGES = 1..stage;

% Decision variables: positions 0 = starting shore, 1 = destination shore
array[STAGES] of var 0..1: wolf_pos;
array[STAGES] of var 0..1: goat_pos;
array[STAGES] of var 0..1: cabbage_pos;
array[STAGES] of var 0..1: boat_pos;

% Initial positions: all on starting shore
constraint wolf_pos[1] = 0;
constraint goat_pos[1] = 0;
constraint cabbage_pos[1] = 0;
constraint boat_pos[1] = 0;

% Final positions: all on destination shore
constraint wolf_pos[stage] = 1;
constraint goat_pos[stage] = 1;
constraint cabbage_pos[stage] = 1;
constraint boat_pos[stage] = 1;

% Transition constraints between stages
constraint
  forall(s in 1..stage-1) (
    % Boat must move each stage
    boat_pos[s] != boat_pos[s+1]
    /\
    % At most one item moves with the boat
    abs(wolf_pos[s] - wolf_pos[s+1])
    + abs(goat_pos[s] - goat_pos[s+1])
    + abs(cabbage_pos[s] - cabbage_pos[s+1]) <= 1
    /\
    % If an item moves, it must move with the boat
    ((wolf_pos[s] != wolf_pos[s+1]) -> wolf_pos[s+1] = boat_pos[s+1])
    /\
    ((goat_pos[s] != goat_pos[s+1]) -> goat_pos[s+1] = boat_pos[s+1])
    /\
    ((cabbage_pos[s] != cabbage_pos[s+1]) -> cabbage_pos[s+1] = boat_pos[s+1])
  );

% Safety constraints: no eating occurs
constraint
  forall(s in STAGES) (
    % Wolf and goat cannot be alone without the boat
    (wolf_pos[s] = goat_pos[s]) -> boat_pos[s] = wolf_pos[s]
    /\
    % Goat and cabbage cannot be alone without the boat
    (goat_pos[s] = cabbage_pos[s]) -> boat_pos[s] = goat_pos[s]
  );

solve satisfy;

output [
  "{",
    "\"wolf_pos\": ", show(wolf_pos), ",",
    "\"goat_pos\": ", show(goat_pos), ",",
    "\"cabbage_pos\": ", show(cabbage_pos), ",",
    "\"boat_pos\": ", show(boat_pos),
  "}"
];
