constraint nations[norway]      == colors[blue] + 1;         % The Norwegian lives immediately right of the blue house
constraint jobs[doctor]         == drinks[milk];             % The doctor drinks milk
constraint nations[japan]       == jobs[diplomat];           % The diplomat is Japanese
