        "\"nations\": " ++ show([nations[n] | n in NATIONS]),
        "\"jobs\": "   ++ show([jobs[j]   | j in JOBS]),
        "\"pets\": "   ++ show([pets[p]   | p in PETS]),
        "\"drinks\": " ++ show([drinks[d] | d in DRINKS])
    ]),
    "}"
];
