include "globals.mzn";

% Input data
int: n_slots = 9;               % Number of slots on each template
int: n_templates = 2;           % Number of templates
int: n_var = 7;                 % Number of design variations
array[1..n_var] of int: demand = [250,255,260,500,500,800,1100];

% Compute an upper bound for the number of sheets needed
int: max_demand = max(demand);

% Decision Variables

% Number of sheets to print for each template
array[1..n_templates] of var 0..max_demand: production;

% Layout: which variation is placed in each slot of each template
array[1..n_templates, 1..n_slots] of var 1..n_var: layout;

% For each template t and variation v, count how many slots of variation v
array[1..n_templates, 1..n_var] of var 0..n_slots: slot_count;

% Constraints

% Link layout and slot_count by a global cardinality constraint per template
constraint
  forall(t in 1..n_templates) (
    global_cardinality(
      [ layout[t,s] | s in 1..n_slots ],
      [ i | i in 1..n_var ],
      [ slot_count[t,i] | i in 1..n_var ]
    )
  );

