int: n = 10;  % Length of the binary sequence

% Decision Variables: sequence of length n with values -1 or +1
array[1..n] of var -1..1: sequence;
constraint forall(i in 1..n) (sequence[i] != 0);

% Compute non-periodic autocorrelations C[k] for k = 1..n-1
array[1..n-1] of var int: C = [
    sum(i in 1..n-k)(sequence[i] * sequence[i+k])
    | k in 1..n-1
];

