int: n = 12;  % Number of pitch-classes

% Decision Variables
% x is the sequence of pitch-classes: a permutation of 0..n-1
array[1..n] of var 0..n-1: x;
% diffs are the intervals between consecutive pitch-classes: must cover 1..n-1
array[1..n-1] of var 1..n-1: diffs;

% Constraints
