constraint all_different(diffs);

% Solve: find any valid all-interval series
solve satisfy;

% Output the sequence x and the intervals diffs in JSON format
output [
    "{",
      "\"x\": ", show(x), ", ",
      "\"diffs\": ", show(diffs),
    "}"
];
