include "globals.mzn";

% Input data
int: deck_width = 5;
int: deck_length = 5;
int: n_containers = 3;
array[1..n_containers] of int: width = [5, 2, 3];
array[1..n_containers] of int: length = [1, 4, 4];
array[1..n_containers] of int: classes = [1, 1, 1];
set of int: CLASS = 1..2;
array[CLASS, CLASS] of int: separation = array2d(CLASS, CLASS, [0,0, 0,0]);

% Decision variables: positions of each container
array[1..n_containers] of var 0..deck_width: left;
array[1..n_containers] of var 0..deck_length: bottom;
array[1..n_containers] of var 0..deck_width: right;
array[1..n_containers] of var 0..deck_length: top;

% Link left/bottom with right/top and enforce deck boundaries
constraint
  forall(i in 1..n_containers) (
    right[i] = left[i] + width[i] /\
    top[i]   = bottom[i] + length[i] /\
    right[i] <= deck_width /\
    top[i]   <= deck_length
  );

% Separation (non-overlap) constraints
constraint
  forall(i, j in 1..n_containers where i < j) (
    let { int: sep = separation[classes[i], classes[j]] } in
      left[i] + width[i] + sep <= left[j]
   \/ left[j] + width[j] + sep <= left[i]
   \/ bottom[i] + length[i] + sep <= bottom[j]
   \/ bottom[j] + length[j] + sep <= bottom[i]
  );

% Loading‐sequence adjacency (north & west touching)
array[1..n_containers] of var bool: wall_north;
array[1..n_containers] of var bool: wall_west;
array[1..n_containers, 1..n_containers] of var bool: overlap_x;
array[1..n_containers, 1..n_containers] of var bool: overlap_y;
array[1..n_containers, 1..n_containers] of var bool: north_pair;
array[1..n_containers, 1..n_containers] of var bool: west_pair;

% A container touches deck wall if its side equals the deck boundary
constraint
  forall(k in 1..n_containers) (
    wall_north[k] <-> (top[k] = deck_length) /\
    wall_west[k]  <-> (left[k] = 0)
  );

% Overlap tests for adjacency
constraint
  forall(k, j in 1..n_containers) (
    overlap_x[k,j]  <-> (left[k] < right[j] /\ left[j] < right[k]) /\
    overlap_y[k,j]  <-> (bottom[k] < top[j] /\ bottom[j] < top[k]) /\
    north_pair[k,j] <-> (bottom[j] = top[k] /\ overlap_x[k,j]) /\
    west_pair[k,j]  <-> (right[j] = left[k] /\ overlap_y[k,j])
  );

% Enforce that each container (except the first) touches north and west
constraint
  forall(k in 2..n_containers) (
    bool2int(wall_north[k]) + sum(j in 1..k-1)(bool2int(north_pair[k,j])) >= 1 /\
    bool2int(wall_west[k])  + sum(j in 1..k-1)(bool2int(west_pair[k,j]))  >= 1
  );

solve satisfy;

output [
  "{",
  join(",", [
    "\"" ++ "left" ++ "\": " ++ show(left),
    "\"" ++ "right" ++ "\": " ++ show(right),
    "\"" ++ "top" ++ "\": " ++ show(top),
    "\"" ++ "bottom" ++ "\": " ++ show(bottom)
  ]),
  "}"
];
