```minizinc
include "globals.mzn";

% Input data
int: n_teams = 9;
int: n_days = 18;
set of int: Teams = 1..n_teams;
set of int: Days = 1..n_days;

% Mirroring scheme
array[1..9] of int: mirror_r1 = [1,2,3,4,5,6,7,10,11];
array[1..9] of int: mirror_r2 = [8,9,12,13,14,15,16,17,18];

% Rival mapping (0 means no rival)
array[Teams] of int: rival = [4,6,0,1,8,2,9,5,7];

% Constrained match pairs (Wake=9, UNC=6; Wake=9,Duke=2; GT=4,UNC=6; GT=4,Duke=2)
array[1..4,2] of int: cons_pairs = [|9,6|, 9,2|, 4,6|, 4,2|];

% Weekend and first-five-weekends
set of int: Weekend = {d | d in Days where d mod 2 == 0};
set of int: First5W = {d | d in Weekend where d <= 10};

% Decision variables
% config[t,d] = opponent team index (0 = bye)
array[Teams, Days] of var 0..n_teams: config;
% where[t,d] = 0 (bye), 1 (home), 2 (away)
array[Teams, Days] of var 0..2: where;

% Double round-robin: each pair meets twice, once home once away
constraint
  forall(i,j in Teams where i < j) (
    sum(d in Days)(bool2int(config[i,d] == j)) = 2 /\
    sum(d in Days)(bool2int(config[i,d] == j /\ where[i,d] == 1)) = 1 /\
    sum(d in Days)(bool2int(config[i,d] == j /\ where[i,d] == 2)) = 1
  );

% Consistency: symmetric fixtures, no self-match, one bye per day
constraint
  forall(t in Teams, d in Days) (
    config[t,d] != t
  );
constraint
  forall(t,i in Teams where i != t, d in Days) (
    config[t,d] == i <-> config[i,d] == t
  );
constraint
  forall(d in Days) (
    sum(t in Teams)(bool2int(config[t,d] == 0)) = 1
  );

% Link config and where: bye <-> where=0; match -> sum where =3 (1+2)
constraint
  forall(t in Teams, d in Days) (
    (config[t,d] == 0 /\ where[t,d] == 0)
    \/
    (config[t,d] > 0 /\ where[t,d] + where[config[t,d],d] == 3)
  );

% Mirroring: same opponent, opposite venue
constraint
  forall(k in 1..9, t in Teams) (
    let { int: r1 = mirror_r1[k], r2 = mirror_r2[k] } in
      config[t,r1] = config[t,r2] /\
      where[t,r1] != where[t,r2]
  );

% No two final aways on days 17 and 18
constraint
  forall(t in Teams) (
    bool2int(where[t,17] == 2) + bool2int(where[t,18] == 2) <= 1
  );

% Home/Away/Bye pattern constraints
constraint
  forall(t in Teams, d in 1..n_days-2) (
    sum(dd in d..d+2)(bool2int(where[t,dd] == 2)) <= 2 /\
    sum(dd in d..d+2)(bool2int(where[t,dd] == 1)) <= 2 /\
    sum(dd in d..d+2)(bool2int(where[t,dd] != 1)) <= 3 /\
    sum(dd in d..d+2)(bool2int(where[t,dd] != 2)) <= 4
  );

% Weekend pattern: each team 4 home, 4 away, 1 bye on weekends
constraint
  forall(t in Teams) (
    sum(d in Weekend)(bool2int(where[t,d] == 1)) = 4 /\
    sum(d in Weekend)(bool2int(where[t,d] == 2)) = 4 /\
    sum(d in Weekend)(bool2int(where[t,d] == 0)) = 1
  );

% First five weekends: at least 2 home or bye
constraint
  forall(t in Teams) (
    sum(d in First5W)(bool2int(where[t,d] != 2)) >= 2
  );

% Rival match on last date (unless vs FSU or bye)
constraint
  forall(t in Teams where rival[t] != 0) (
    (config[t,18] != 3 /\ config[t,18] != 0) -> config[t,18] = rival[t]
  );

% Constrained matches at least once in days 11..18
constraint
  forall(p in 1..4) (
    let { int: a = cons_pairs[p,1], b = cons_pairs[p,2] } in
      sum(d in 11..18)(bool2int(config[a,d] == b)) >= 1
  );

% Opponent sequence constraints
constraint
  % no two consecutive away vs UNC(6) or Duke(2)
  forall(t in Teams, d in 1..n_days-1) (
    not (
      where[t,d] == 2 /\ (config[t,d] == 2 \/ config[t,d] == 6)
      /\
      where[t,d+1] == 2 /\ (config[t,d+1] == 2 \/ config[t,d+1] == 6)
    )
  ) /\
  % no three consecutive vs UNC, Duke, Wake (2,6,9)
  forall(t in Teams, d in 1..n_days-2) (
    sum(dd in d..d+2)(
      bool2int(config[t,dd] == 2 \/ config[t,dd] == 6 \/ config[t,dd] == 9)
    ) <= 2
  );

% Other specific constraints
constraint
  % UNC=6 vs Duke=2 on day 11 and 18
  config[6,11] = 2 /\ config[6,18] = 2 /\
  % UNC vs Clem=1 on day 2
  config[6,2] = 1 /\
  % Duke=2 has bye on day 16
  config[2,16] = 0 /\
  % Wake=9 not home on day 17; bye on day 1
  where[9,17] != 1 /\ config[9,1] = 0 /\
  % Clem=1, Duke=2, UMD=5, Wake=9 not away on day 18
  forall(t in {1,2,5,9})(where[t,18] != 2) /\
  % Clem=1, FSU=3, GT=4, Wake=9 not away on day 1
  forall(t in {1,3,4,9})(where[t,1] != 2) /\
  % FSU=3, NCSt=7 no bye on day 18; UNC=6 no bye on day 1
  config[3,18] != 0 /\ config[7,18] != 0 /\ config[6,1] != 0;

solve satisfy;

output [
  "{",
  "\"config\": ", show(config), ",",
  "\"where\": ", show(where),
  "}"
];
```

