include "globals.mzn";

% Input data
int: n_boats = 5;           % Number of boats
int: n_periods = 4;         % Number of periods
array[1..n_boats] of int: capacity = [6, 8, 12, 12, 12];
array[1..n_boats] of int: crew_size = [2, 2, 2, 2, 4];

% Decision variables
array[1..n_boats] of var bool: is_host;                                     % which boats are hosts
array[1..n_periods, 1..n_boats] of var 1..n_boats: visits;                  % visits[p,g] = host boat that boat g visits in period p

% Constraints

% A boat g is host if and only if it "visits" itself every period
constraint
  forall(p in 1..n_periods, g in 1..n_boats) (
    (visits[p,g] == g) <-> is_host[g]
  );

% Every visit must be to a host boat
constraint
  forall(p in 1..n_periods, g in 1..n_boats) (
    is_host[visits[p,g]]
  );

% Capacity constraint: for each boat h in each period, total onboard ≤ capacity
constraint
  forall(p in 1..n_periods, h in 1..n_boats) (
    sum([ bool2int(visits[p,g] == h) * crew_size[g] | g in 1..n_boats ])
    <= capacity[h]
  );

% A guest boat cannot visit the same host more than once
constraint
  forall(g in 1..n_boats) (
    not is_host[g] -> alldifferent([ visits[p,g] | p in 1..n_periods ])
  );

% Two guest crews meet at most once (i.e., visit the same host no more than once)
constraint
  forall(g1, g2 in 1..n_boats where g1 < g2) (
    (not is_host[g1] /\ not is_host[g2]) ->
      sum([ bool2int(visits[p,g1] == visits[p,g2]) | p in 1..n_periods ]) <= 1
  );

% Objective: minimize number of hosts
solve minimize sum([ bool2int(is_host[b]) | b in 1..n_boats ]);

% Output in JSON format
output [
  "{",
  join(",", [
    "\"visits\": [" ++
      join(",", [ "[" ++ join(",", [ show(visits[p,g]) | g in 1..n_boats ]) ++ "]"
                 | p in 1..n_periods ]) ++ "]",
    "\"is_host\": " ++ show(is_host)
  ]),
  "}"
];
```

