% Input data
int: n = 13;               % Number of balls
int: c = 3;                % Number of boxes
set of int: J = 1..c;      % Box indices

% Decision variables: balls[i] = box assigned to ball i
array[1..n] of var 1..c: balls;

% Constraints:
% For any triple (x,y,z) with x + y = z, forbid all three in same box j
constraint
  forall(x, y in 1..n where x < y && x + y <= n) (
    let { int: z = x + y } in
      forall(j in J)(
        (balls[x] != j) \/ (balls[y] != j) \/ (balls[z] != j)
      )
  );

solve satisfy;

% Output the assignment as JSON
output [
  "{",
    "\"balls\": ", show(balls),
  "}"
];
