include "globals.mzn";

% Input data
int: n_teams = 8;                % Number of teams (must be even)
int: weeks = n_teams - 1;        % Weeks in a single round robin
int: periods = n_teams div 2;    % Matches per week
int: total_weeks = 2 * weeks;    % Weeks in double round robin

% First‐half decision variables
array[1..weeks, 1..periods] of var 0..n_teams-1: home1;
array[1..weeks, 1..periods] of var 0..n_teams-1: away1;

% Full schedule (home and away) including the mirrored second half
array[1..total_weeks, 1..periods] of var 0..n_teams-1: home;
array[1..total_weeks, 1..periods] of var 0..n_teams-1: away;

% Link first half and second half (swap home/away in second half)
constraint
  forall(w in 1..weeks, p in 1..periods) (
    home[w,p] = home1[w,p]
    /\ away[w,p] = away1[w,p]
    /\ home[w+weeks,p] = away1[w,p]
    /\ away[w+weeks,p] = home1[w,p]
  );

% 1) Each team plays exactly once per week in the first half
constraint
  forall(w in 1..weeks) (
    all_different([home1[w,p] | p in 1..periods] ++ [away1[w,p] | p in 1..periods])
  );

% 2) Each team meets every other team exactly once in the first half
constraint
  forall(i,j in 0..n_teams-1 where i < j) (
    sum([ bool2int(home1[w,p] = i /\ away1[w,p] = j)
        + bool2int(home1[w,p] = j /\ away1[w,p] = i)
        | w in 1..weeks, p in 1..periods ]) = 1
  );

% 3) Each team appears at most twice in each period across the first half
constraint
  forall(t in 0..n_teams-1, p in 1..periods) (
    sum([ bool2int(home1[w,p] = t \/ away1[w,p] = t) | w in 1..weeks ]) <= 2
  );

solve satisfy;

% Output full home and away schedule in JSON
output [
  "{",
    "\"home\": ", show(home), ",",
    "\"away\": ", show(away),
  "}"
];
```

