include "globals.mzn";

% Input data
int: v = 9;    % Number of distinct objects
int: b = 12;   % Number of blocks
int: r = 4;    % Number of blocks each object occurs in
int: k = 3;    % Number of objects each block contains
int: l = 1;    % Number of blocks in which each pair of distinct objects occurs together

% Decision variable: incidence matrix of size v x b with binary entries
array[1..v, 1..b] of var 0..1: matrix;

% Each object occurs in exactly r blocks (row sums)
constraint
  forall(i in 1..v) (
    sum(c in 1..b)(matrix[i,c]) = r
  );

% Each block contains exactly k objects (column sums)
constraint
  forall(j in 1..b) (
    sum(i in 1..v)(matrix[i,j]) = k
  );

% Every pair of distinct objects occurs together in exactly l blocks
constraint
  forall(i, j in 1..v where i < j) (
    sum(c in 1..b)(matrix[i,c] * matrix[j,c]) = l
  );

solve satisfy;

% Output the incidence matrix in JSON format
output [
  "{",
  "\"matrix\": ", show(matrix),
  "}"
];
```

