include "globals.mzn";

% Number of words and length of each word
int: n = 8;
int: L = 8;

% Words encoded as integers: 1=A, 2=C, 3=G, 4=T
array[1..n, 1..L] of var 1..4: words;

% 1) Each word has exactly 4 symbols from {C=2, G=3}
constraint
  forall(i in 1..n) (
    sum([ bool2int(words[i,j] == 2 \/ words[i,j] == 3) | j in 1..L ]) = 4
  );

% 2) Hamming distance between any two distinct words >= 4
constraint
  forall(i, j in 1..n where i < j) (
    sum([ bool2int(words[i,k] != words[j,k]) | k in 1..L ]) >= 4
  );

% 3) Hamming distance between reverse of word i and complement of word j >= 4
%    Complement mapping uses comp(x) = 5 - x (1<->4, 2<->3)
constraint
  forall(i, j in 1..n) (
    sum([ bool2int(words[i, L+1-k] != 5 - words[j,k]) | k in 1..L ]) >= 4
  );

solve satisfy;

output [
  "{",
  "\"words\": ", show(words),
  "}"
];
```

