          /\ (sets[b,1] == v \/ sets[b,2] == v \/ sets[b,3] == v)
        )
    ) == 1
);

% Solve
solve satisfy;

% Output in JSON format
output [
    "{",
    "\"sets\": ", show(sets),
    "}"
];
