% Input data
int: n = 12;  % The number N

% Decision variable: inA[i] = true if i is in set A, false if in B
array[1..n] of var bool: inA;

% Cardinality constraint: |A| = |B| = n/2
constraint
    sum([ bool2int(inA[i]) | i in 1..n ]) = n div 2;

% Sum constraint: sum(A) = sum(B) = total_sum/2
constraint
    sum([ i * bool2int(inA[i]) | i in 1..n ]) =
    (n * (n + 1) div 2) div 2;

% Sum of squares constraint: sum(i^2 for i in A) = total_squares/2
constraint
    sum([ i * i * bool2int(inA[i]) | i in 1..n ]) =
    (n * (n + 1) * (2 * n + 1) div 6) div 2;

solve satisfy;

% Output sets A and B in JSON format
output [
    "{",
    "\"A\": ", "[" ++ join(",", [ show(i) | i in 1..n where inA[i] ]) ++ "]", ",",
    "\"B\": ", "[" ++ join(",", [ show(i) | i in 1..n where not inA[i] ]) ++ "]",
    "}"
];
