array[1..N,1..N] of var 0..1: m;

% Degree of each vertex
array[1..N] of var 1..N-1: deg;

% No loops and symmetry
constraint forall(i in 1..N)( m[i,i] = 0 );
constraint forall(i,j in 1..N where i < j)( m[i,j] = m[j,i] );

% Define degrees
constraint forall(i in 1..N)(
    deg[i] = sum(j in 1..N)( m[i,j] )
);

% Non-increasing degree sequence
constraint forall(i in 1..N-1)(
    deg[i] >= deg[i+1]
);

% Each degree > 0 and divisible by 3
constraint forall(i in 1..N)(
    deg[i] mod 3 = 0
);

% Sum of degrees ≡ 0 (mod 12)
constraint sum(i in 1..N)( deg[i] ) mod 12 = 0;

% Diamond-free: any 4 vertices have at most 4 edges among them
constraint
    forall(a,b,c,d in 1..N where a < b /\ b < c /\ c < d)(
        sum([
            m[a,b], m[a,c], m[a,d],
            m[b,c], m[b,d],
            m[c,d]
        ]) <= 4
    );

solve satisfy;

output [
    "{",
    "\"matrix\": ", show([ [ m[i,j] | j in 1..N ] | i in 1..N ]),
    "}"
];
```

