% We use a 3x3 grid; the center (2,2) is empty (0), the other 8 cells hold digits 1..8
array[1..3, 1..3] of var 0..8: positions;

% Fix center to 0 (empty)
constraint positions[2,2] = 0;

% Non-center cells must be between 1 and 8
constraint
  forall(i, j in 1..3 where not (i == 2 /\ j == 2)) (
    positions[i,j] >= 1 /\ positions[i,j] <= 8
  );

% All 8 non-center values must be distinct
constraint
  all_different([ positions[i,j] | i, j in 1..3 where not (i == 2 /\ j == 2) ]);

% Sum constraints for each square cell:
%   - (1,2) square is sum of (1,1) + (1,3)
%   - (2,1) square is sum of (1,1) + (3,1)
%   - (2,3) square is sum of (1,3) + (3,3)
%   - (3,2) square is sum of (3,1) + (3,3)
