constraint positions[2,1] = positions[1,1] + positions[3,1];
constraint positions[2,3] = positions[1,3] + positions[3,3];
constraint positions[3,2] = positions[3,1] + positions[3,3];

solve satisfy;

output [
  "{",
  "\"positions\": ", show(positions),
