% Decision variables: ages of the three sons, sorted non-increasingly
var 1..36: A1;  % oldest
var 1..36: A2;
var 1..36: A3;

% Enforce ordering: A1 >= A2 >= A3
constraint A1 >= A2;
constraint A2 >= A3;

% 1) Product of ages is 36
constraint A1 * A2 * A3 = 36;

% 2) The mathematician needed more information after hearing the sum:
%    this forces the sum to be ambiguous among factorizations of 36,
%    which happens exactly when A1 + A2 + A3 = 13.
constraint A1 + A2 + A3 = 13;

