% Inverse maps: which_surname[s] = person index who has surname s
array[SURNAME] of var PERSON: which_surname;

% All surnames are different and all allergies are different
constraint all_different(surname);
constraint all_different(allergy);

% Link inverse arrays
constraint forall(p in PERSON)(
    % Person p has allergy allergy[p], so which_food[allergy[p]] == p
    element(allergy[p], which_food, p)
