% Problem data
int: n = 27;
int: m = 5;
int: N = n + 2;        % Total length of the series S

% We consider values 0..n for the self‐descriptive counts
set of int: Value = 0..n;

% Decision variables: the series S = (s[0], ..., s[n+1])
% Each s[i] is a count and hence in 0..n
array [0..n+1] of var Value: s;

% The last element s[n+1] is fixed to m
constraint s[n+1] = m;

% We introduce auxiliary variables counts[i] = number of occurrences of i in S
array [Value] of var 0..N: counts;
array [Value] of int: cover = [i | i in Value];

% Enforce counts by global_cardinality: for each i in 0..n, counts[i] is
% the number of times i appears in s
constraint global_cardinality(s, cover, counts);

% Link counts to the series definition: for each i in 0..n, counts[i] = s[i]
constraint forall(i in Value)(counts[i] = s[i]);

% The total of all entries in S must equal its length N
constraint sum(i in 0..n+1)(s[i]) = N;

solve satisfy;

% Output the series S in JSON format under key "s"
output [
  "{\"s\": ", show([s[i] | i in 0..n+1]), "}"
];
```

