% Symmetry breaking: sort the bale weights in non-decreasing order
constraint
  forall(i in 1..n-1)(
    bales[i] <= bales[i+1]
  );

solve satisfy;

% Output in JSON format
output [
  "{",
    "\"bales\": ", show(bales),
  "}"
];
