% Decision variables: number of each fruit (at least 1 of each, at most 100)
var 1..100: bananas;
var 1..100: oranges;
var 1..100: mangoes;
var 1..100: apples;

% 1) Total fruits constraint
constraint bananas + oranges + mangoes + apples = 100;

% 2) Total cost constraint:
%    bananas cost 3 dollars per 5  -> 3/5 dollars each
%    oranges cost 5 dollars per 7  -> 5/7 dollars each
%    mangoes cost 7 dollars per 9  -> 7/9 dollars each
%    apples cost 9 dollars per 3  -> 3 dollars each
%
% Multiply both sides by 315 (LCM of 5,7,9,1) to stay in integers:
%    315*(3/5)*bananas  + 315*(5/7)*oranges  + 315*(7/9)*mangoes  + 315*3*apples  = 315*100
% => 189*bananas + 225*oranges + 245*mangoes + 945*apples = 31500
constraint
    189 * bananas
  + 225 * oranges
  + 245 * mangoes
  + 945 * apples
  = 31500;

% 3) Minimize the disliked fruits (bananas + apples)
solve minimize bananas + apples;

% Output as JSON
output [
  "{",
    join(",",
      [ "\"" ++ "bananas" ++ "\": " ++ show(bananas),
        "\"" ++ "oranges" ++ "\": " ++ show(oranges),
        "\"" ++ "mangoes" ++ "\": " ++ show(mangoes),
        "\"" ++ "apples" ++ "\": " ++ show(apples)
      ]
    ),
  "}"
];
```

