% Adjacency matrix of allowed neighbors:
% 0=Andrew,1=Betty,2=Cara,3=Dave,4=Erica,5=Frank
array[0..5,0..5] of bool: allowed = array2d(0..5,0..5,
    [ false, false, false,  true, false,  true,   % 0
      false, false,  true, false,  true, false,   % 1
      false,  true, false, false, false,  true,   % 2
       true, false, false, false,  true, false,   % 3
      false,  true, false,  true, false, false,   % 4
       true, false,  true, false, false, false    % 5
    ]);

% Decision variables: a circular seating of 6 guests
array[1..6] of var 0..5: x;
constraint all_different(x);
constraint x[1] = 0;  % fix Andrew at position 1 to break rotational symmetry

% Compute conflicts on each adjacent pair (including last-to-first)
array[1..6] of var 0..1: c;
constraint
  forall(i in 1..6) (
    let { int: j = if i < 6 then i+1 else 1 } in
      c[i] = bool2int(not allowed[x[i], x[j]])
  );

% Objective: minimize total conflicts
var int: total_conflict = sum(c);
solve minimize total_conflict;

output [
    "{",
    "\"x\": ", show(x),
    "}"
];
```

