include "globals.mzn";

% Input data
int: n = 5;
int: N = n * n;

% Decision Variables
% x[i,j] is the number placed in cell (i,j)
array[1..n, 1..n] of var 1..N: x;

% r[k], c[k] are the row and column of number k
array[1..N] of var 1..n: r;
array[1..N] of var 1..n: c;

% id[k] is the index in the flattened grid corresponding to (r[k],c[k])
array[1..N] of var 1..N: id =
    [ (r[k] - 1) * n + c[k] | k in 1..N ];

% Flattened view of x in row-major order
array[1..N] of var 1..N: flat = [ x[i,j] | i in 1..n, j in 1..n ];

% Constraints

% 1) Every cell has a distinct number
constraint
    alldifferent([ x[i,j] | i,j in 1..n ]);

% 2) Each number k occupies exactly one cell (distinct (r,c) pairs)
constraint
    alldifferent(id);

% 3) Link the position variables (r,c) with x via element/3
constraint
    forall(k in 1..N) (
        element(id[k], flat, k)
    );

% 4) Movement constraints between consecutive numbers
%    - Type I: horizontal or vertical step of exactly 3 (gap of 2)
%    - Type II: diagonal step of exactly 2 (gap of 1)
constraint
    forall(k in 1..N-1) (
      let {
        var int: dr = abs(r[k+1] - r[k]),
        var int: dc = abs(c[k+1] - c[k])
      } in
        (dr = 3 /\ dc = 0) \/
        (dr = 0 /\ dc = 3) \/
        (dr = 2 /\ dc = 2)
    );

% Solve: find any valid filling
solve satisfy;

% Output the completed grid as JSON
output [
    "{",
    "\"x\": ", show([ [ x[i,j] | j in 1..n ] | i in 1..n ]),
    "}"
];
```

