% Persons: 1=X, 2=Y, 3=Z
% Nationalities: 1=American, 2=English, 3=French

% Seating around table: seat[i] = person sitting at position i (1..3)
array[1..3] of var 1..3: seat;
% Inverse: pos[p] = position of person p
array[1..3] of var 1..3: pos;
constraint inverse(seat, pos);
constraint all_different(seat);

% Nationality of each person: nat[p] in 1..3
array[1..3] of var 1..3: nat;
constraint all_different(nat);

% Inverse: npos[n] = person who has nationality n
array[1..3] of var 1..3: npos;
constraint inverse(nat, npos);

% Helper functions for successor and predecessor around a 3-seat table
function int: succ(i) = if i < 3 then i + 1 else 1 endif;
function int: pred(i) = if i > 1 then i - 1 else 3 endif;

% Clue 1: Y (person 2) passed three hearts to the American.
% Y is at position pos[2]; they pass to succ(pos[2]); the recipient is seat[ succ(pos[2]) ] 
% That recipient must have nationality = American (1).
constraint nat[ seat[ succ(pos[2]) ] ] = 1;

% Clue 2: X (person 1) passed cards to the person who passed to the Frenchwoman.
% Person who passed to Frenchwoman is the one sitting at pred(posFrench),
% where posFrench = position of npos[3] (the Frenchwoman).
var 1..3: posFrench = pos[npos[3]];
var 1..3: predFrench = pred(posFrench);
% The person who passed to the Frenchwoman is at seat[predFrench].
% X passes to succ(pos[1]), so:
constraint seat[ succ(pos[1]) ] = seat[ predFrench ];

solve satisfy;

output [
    "{",
    join(",", [
      "\"x\": " ++ show(nat[1] - 1),
      "\"y\": " ++ show(nat[2] - 1),
      "\"z\": " ++ show(nat[3] - 1),
      "\"american\": " ++ show(npos[1] - 1),
      "\"english\": " ++ show(npos[2] - 1),
      "\"french\": " ++ show(npos[3] - 1)
    ]),
    "}"
];
