constraint open_warehouse[1] -> open_warehouse[2];

% 2) No more than 3 warehouses can be open
constraint sum([bool2int(open_warehouse[i]) | i in 1..n]) <= 3;

% 3) Either Atlanta (4) or Los Angeles (2) must be open
constraint open_warehouse[2] \/ open_warehouse[4];

% Capacity constraint: a warehouse ships only if open, and max total per warehouse
constraint
  forall(i in 1..n) (
    sum(j in 1..m)(ships[i,j]) <= max_shipping * bool2int(open_warehouse[i])
  );

% Demand satisfaction: each region's demand must be met
constraint
  forall(j in 1..m) (
