include "globals.mzn";

int: num_moves = 3;
array[1..3] of int: init = [1, 0, 1];  % 1 = tail, 0 = head

% Decision variables: each move flips two distinct coins
array[1..num_moves, 1..2] of var 1..3: steps;

% Boolean state of each coin at each time (false = head, true = tail)
array[0..num_moves, 1..3] of var bool: state;
% Indicates if coin i is flipped in move m
array[1..num_moves, 1..3] of var bool: flip;

% Initialize the starting state
constraint
  forall(i in 1..3)(
    state[0,i] = (init[i] == 1)
  );

% Define which coins are flipped in each move
constraint
  forall(m in 1..num_moves, i in 1..3)(
    flip[m,i] <-> (steps[m,1] = i \/ steps[m,2] = i)
  );

% State transition: coin toggles if it's flipped
constraint
  forall(m in 1..num_moves, i in 1..3)(
    xor(state[m-1,i], flip[m,i]) = state[m,i]
  );

% In each move the two flipped coins must be different
constraint
  forall(m in 1..num_moves)(
    steps[m,1] < steps[m,2]
  );

% Final state must be all heads (false) or all tails (true)
constraint
  or([
    and([ state[num_moves,i] | i in 1..3 ]),
    and([ not(state[num_moves,i]) | i in 1..3 ])
  ]);

solve satisfy;

output [
  "{",
  "\"steps\": [",
    join(",",
      [ "[" ++ show(steps[r,1]) ++ "," ++ show(steps[r,2]) ++ "]"
      | r in 1..num_moves
      ]
    ),
  "]",
  "}"
];
```

